class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        if abs(k) > 900:
            return -1

        OFFSET = 1000
        RANGE = 2001
        SIZE = RANGE * 2

        # dp[s*2+p]: all achievable products (including empty subsequence)
        # ne[s*2+p]: achievable products from non-empty subsequences only
        dp = [set() for _ in range(SIZE)]
        ne = [set() for _ in range(SIZE)]
        dp[OFFSET * 2].add(1)  # empty subsequence: sum=0, even length, product=1
        active = {OFFSET * 2}

        for x in nums:
            new_dp = [s.copy() for s in dp]
            new_ne = [s.copy() for s in ne]
            new_active = set(active)

            for idx in active:
                s = idx // 2
                p = idx % 2

                if p == 0:
                    # Next element goes at even index → add to sum
                    ns = s + x
                    if 0 <= ns < RANGE:
                        nidx = ns * 2 + 1
                        if x == 0:
                            new_dp[nidx].add(0)
                            new_ne[nidx].add(0)
                        else:
                            for prod in dp[idx]:
                                np = prod * x
                                if np <= limit:
                                    new_dp[nidx].add(np)
                                    new_ne[nidx].add(np)
                        new_active.add(nidx)
                else:
                    # Next element goes at odd index → subtract from sum
                    ns = s - x
                    if 0 <= ns < RANGE:
                        nidx = ns * 2
                        if x == 0:
                            new_dp[nidx].add(0)
                            new_ne[nidx].add(0)
                        else:
                            for prod in dp[idx]:
                                np = prod * x
                                if np <= limit:
                                    new_dp[nidx].add(np)
                                    new_ne[nidx].add(np)
                        new_active.add(nidx)

            dp = new_dp
            ne = new_ne
            active = new_active

        if 0 <= k + OFFSET < RANGE:
            prods = ne[(k + OFFSET) * 2] | ne[(k + OFFSET) * 2 + 1]
            if prods:
                return max(prods)
        return -1

