class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        OFFSET = 900
        SIZE = 1801  # covers sums from -900 to 900

        # dp[p][s] = max product for non-empty subsequence with parity p and sum s
        # -1 means not reachable
        dp = [[-1] * SIZE for _ in range(2)]

        for x in nums:
            new_dp = [row[:] for row in dp]

            # Start a new subsequence with just x (length 1, odd parity, sum = x)
            if x <= limit:
                new_dp[1][x + OFFSET] = max(new_dp[1][x + OFFSET], x)

            # Extend existing subsequences
            for p in range(2):
                for s in range(SIZE):
                    if dp[p][s] < 0:
                        continue
                    cur_sum = s - OFFSET
                    if p == 0:
                        # Current length is even, next element at even index -> add
                        new_p = 1
                        new_sum = cur_sum + x
                    else:
                        # Current length is odd, next element at odd index -> subtract
                        new_p = 0
                        new_sum = cur_sum - x

                    if -OFFSET <= new_sum <= OFFSET:
                        new_prod = dp[p][s] * x
                        if new_prod <= limit:
                            idx = new_sum + OFFSET
                            new_dp[new_p][idx] = max(new_dp[new_p][idx], new_prod)

            dp = new_dp

        if -OFFSET <= k <= OFFSET:
            ans = max(dp[0][k + OFFSET], dp[1][k + OFFSET])
            return ans if ans >= 0 else -1
        else:
            return -1

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        max_sum = sum(nums)
        offset = max_sum
        size = 2 * max_sum + 1

        # dp[p][j] = max product (<= limit) for non-empty subsequence
        # with alt sum = j - offset, next position parity = p
        # -1 means no valid subsequence
        dp = [[-1] * size for _ in range(2)]

        for x in nums:
            new_dp = [row[:] for row in dp]  # skip case: carry over

            # Extend existing subsequences
            for p in range(2):
                for j in range(size):
                    if dp[p][j] == -1:
                        continue
                    prod = dp[p][j]
                    new_prod = prod * x
                    if new_prod <= limit:
                        if p == 0:
                            nj = j + x
                        else:
                            nj = j - x
                        if 0 <= nj < size:
                            new_dp[1 - p][nj] = max(new_dp[1 - p][nj], new_prod)

            # Start a new subsequence with just x (x is at position 0, which is even)
            nj = offset + x
            if 0 <= nj < size and x <= limit:
                new_dp[1][nj] = max(new_dp[1][nj], x)

            dp = new_dp

        # Answer: look for alt sum = k, either parity
        ans = -1
        target = k + offset
        if 0 <= target < size:
            ans = max(dp[0][target], dp[1][target])

        return ans

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # states[parity] = set of (alternating_sum, product, is_non_empty)
        # parity 0: next chosen element goes at even position (added to sum)
        # parity 1: next chosen element goes at odd position (subtracted from sum)
        states = [{(0, 1, False)}, set()]

        for x in nums:
            new_states = [set(states[0]), set(states[1])]

            # From parity 0: we add x (even position)
            for (s, p, ne) in states[0]:
                new_p = p * x
                if new_p <= limit:
                    new_states[1].add((s + x, new_p, True))

            # From parity 1: we subtract x (odd position)
            for (s, p, ne) in states[1]:
                new_p = p * x
                if new_p <= limit:
                    new_states[0].add((s - x, new_p, True))

            states = new_states

        # Find max product where alternating sum == k and subsequence is non-empty
        best = -1
        for parity in (0, 1):
            for (s, p, ne) in states[parity]:
                if s == k and ne:
                    best = max(best, p)

        return best

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # states: set of (alternating_sum, product, parity)
        # parity 0 = even length so far (next sign is +)
        # parity 1 = odd length so far (next sign is -)
        states = set()

        for num in nums:
            new_states = set(states)  # option to skip num
            for (s, p, par) in states:
                ns = s + num if par == 0 else s - num
                np = p * num
                if np <= limit:
                    new_states.add((ns, np, 1 - par))
            # Start a new subsequence with just this element
            if num <= limit:
                new_states.add((num, num, 1))
            states = new_states

        best = -1
        for (s, p, par) in states:
            if s == k and p > best:
                best = p
        return best

