class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        max_sum = sum(nums)
        offset = max_sum
        size = 2 * max_sum + 1

        # dp[started][parity][s + offset] = max product (-1 means unreachable)
        dp = [[[-1] * size for _ in range(2)] for _ in range(2)]

        # Initial state: not started, next at even index, sum=0, product=1
        dp[0][0][offset] = 1

        for num in nums:
            # Copy current state (option to skip num)
            new_dp = [[[v for v in row] for row in layer] for layer in dp]
            for started in range(2):
                for parity in range(2):
                    for s_idx in range(size):
                        prod = dp[started][parity][s_idx]
                        if prod < 0:
                            continue
                        s = s_idx - offset
                        # Take this element
                        new_s = s + num if parity == 0 else s - num
                        new_parity = 1 - parity
                        new_prod = prod * num
                        if new_prod <= limit:
                            new_s_idx = new_s + offset
                            if 0 <= new_s_idx < size:
                                if new_prod > new_dp[1][new_parity][new_s_idx]:
                                    new_dp[1][new_parity][new_s_idx] = new_prod
            dp = new_dp

        k_idx = k + offset
        if 0 <= k_idx < size:
            ans = max(dp[1][0][k_idx], dp[1][1][k_idx])
            return ans if ans >= 0 else -1
        return -1

