from collections import defaultdict

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)

        # dp maps (parity, alt_sum) -> set of products (-1 for exceeded)
        dp = {}

        for i, x in enumerate(nums):
            remaining = n - i - 1
            new_dp = defaultdict(set)

            for (p, s), prods in dp.items():
                # Skip x: carry over state
                new_dp[(p, s)].update(prods)

                # Include x
                new_p = 1 - p
                new_s = s + x if p == 0 else s - x

                if x == 0:
                    new_dp[(new_p, new_s)].add(0)
                elif x == 1:
                    new_dp[(new_p, new_s)].update(prods)
                else:
                    for prod in prods:
                        if prod == -1:
                            new_dp[(new_p, new_s)].add(-1)
                        elif prod == 0:
                            new_dp[(new_p, new_s)].add(0)
                        else:
                            np_ = prod * x
                            if np_ > limit:
                                new_dp[(new_p, new_s)].add(-1)
                            else:
                                new_dp[(new_p, new_s)].add(np_)

            # Start a new subsequence with just x
            if x == 0:
                new_dp[(1, 0)].add(0)
            elif x <= limit:
                new_dp[(1, x)].add(x)
            else:
                new_dp[(1, x)].add(-1)

            # Prune states that can never reach k with remaining elements
            if remaining > 0:
                max_change = 12 * remaining
                dp = {(p, s): prods for (p, s), prods in new_dp.items()
                      if abs(s - k) <= max_change}
            else:
                dp = {(p, s): prods for (p, s), prods in new_dp.items()
                      if s == k}

            if not dp:
                return -1

        result = -1
        for p in [0, 1]:
            if (p, k) in dp:
                for prod in dp[(p, k)]:
                    if prod >= 0:
                        result = max(result, prod)

        return result

