from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        dp = set()
        for x in nums:
            new_states = set()
            # Start a new subsequence with just x
            if x <= limit:
                new_states.add((1, x, x))
            # Extend existing subsequences
            for (parity, s, p) in dp:
                if parity == 0:
                    # even-length subsequence, next element at odd index -> subtract
                    ns, np = s + x, p * x
                else:
                    # odd-length subsequence, next element at even index -> add
                    ns, np = s - x, p * x
                if np <= limit:
                    new_states.add((1 - parity, ns, np))
            dp = dp | new_states

        # Find max product among states with sum == k
        best = -1
        for (parity, s, p) in dp:
            if s == k and p > best:
                best = p
        return best

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        from collections import defaultdict

        m = len(conflictingPairs)

        # Normalize: ensure a < b
        pairs = []
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            pairs.append((a, b))

        INF = n + 1

        # Step 1: Compute first[i] and second[i] for each position i
        # first[i] = min b among pairs with a >= i
        # second[i] = second min b (strictly greater than first[i]) among pairs with a >= i
        pairs_by_a = defaultdict(list)
        for a, b in pairs:
            pairs_by_a[a].append(b)

        first = [INF] * (n + 2)
        second = [INF] * (n + 2)

        min1 = INF
        min2 = INF

        for i in range(n, 0, -1):
            for b in pairs_by_a[i]:
                if b < min1:
                    min2 = min1
                    min1 = b
                elif b > min1 and b < min2:
                    min2 = b
            first[i] = min1
            second[i] = min2

        # Total valid subarrays with all pairs present
        total = 0
        for i in range(1, n + 1):
            total += first[i] - i

        # Step 2: For each pair, compute max_a_strictly_less (max a' where b' < b)
        pair_indices = list(range(m))
        pair_indices.sort(key=lambda idx: pairs[idx][1])

        max_a_strictly_less = [0] * m
        running_max_a = 0
        j = 0
        for k in range(m):
            idx = pair_indices[k]
            b_val = pairs[idx][1]
            while j < m and pairs[pair_indices[j]][1] < b_val:
                running_max_a = max(running_max_a, pairs[pair_indices[j]][0])
                j += 1
            max_a_strictly_less[idx] = running_max_a

        # Step 3: For each pair, compute max_a_equal_excl (max a' among other pairs with same b)
        pairs_by_b = defaultdict(list)
        for idx, (a, b) in enumerate(pairs):
            pairs_by_b[b].append((a, idx))

        max_a_equal_excl = [0] * m
        for b_val, group in pairs_by_b.items():
            if len(group) == 1:
                max_a_equal_excl[group[0][1]] = 0
            else:
                group_sorted = sorted(group, key=lambda x: x[0], reverse=True)
                for i, (a_val, idx) in enumerate(group_sorted):
                    if i == 0:
                        max_a_equal_excl[idx] = group_sorted[1][0]
                    else:
                        max_a_equal_excl[idx] = group_sorted[0][0]

        # Step 4: Prefix sum of second[i]
        prefix_second = [0] * (n + 2)
        for i in range(1, n + 1):
            prefix_second[i] = prefix_second[i - 1] + second[i]

        # Step 5: Compute best gain from removing one pair
        best_gain = 0
        for idx in range(m):
            a, b = pairs[idx]
            lo = max(max_a_strictly_less[idx], max_a_equal_excl[idx])
            if lo < a:
                gain = (prefix_second[a] - prefix_second[lo]) - (a - lo) * b
                if gain > best_gain:
                    best_gain = gain

        return total + best_gain

