    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        from collections import defaultdict
        import bisect

        pairs = []
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            pairs.append((a, b))

        m = len(pairs)
        INF = n + 1

        # Group b values by a
        b_by_a = defaultdict(list)
        for a, b in pairs:
            b_by_a[a].append(b)

        # Sweep from right to left: compute right[i] and m2_arr[i]
        right = [0] * (n + 2)
        m2_arr = [0] * (n + 2)

        m1 = INF
        cnt1 = 0
        m2 = INF

        for i in range(n, 0, -1):
            for b in b_by_a.get(i, []):
                if b < m1:
                    m2 = m1
                    m1 = b
                    cnt1 = 1
                elif b == m1:
                    cnt1 += 1
                elif b < m2:
                    m2 = b
            right[i] = m1
            m2_arr[i] = m2

        # Total valid subarrays with all pairs
        total = sum(right[i] - i for i in range(1, n + 1))

        # Compute A[k]: max a_j among pairs j != k with same b value
        a_by_b = defaultdict(list)
        for idx, (a, b) in enumerate(pairs):
            a_by_b[b].append((a, idx))

        A = [0] * m
        for b_val, lst in a_by_b.items():
            lst.sort(reverse=True)
            if len(lst) == 1:
                A[lst[0][1]] = 0
            else:
                for pos in range(len(lst)):
                    if pos == 0:
                        A[lst[0][1]] = lst[1][0]
                    else:
                        A[lst[pos][1]] = lst[0][0]

        # Prefix sums of m2_arr for range sum queries
        prefix_m2 = [0] * (n + 2)
        for i in range(1, n + 1):
            prefix_m2[i] = prefix_m2[i - 1] + m2_arr[i]

        # right is non-decreasing; use binary search to find ranges
        right_arr = right[1:n + 1]

        best_improvement = 0
        for k, (a_k, b_k) in enumerate(pairs):
            # Find 1-indexed range [L, R] where right[i] == b_k
            L = bisect.bisect_left(right_arr, b_k) + 1
            R = bisect.bisect_right(right_arr, b_k)

            if L > R:
                continue

            # Pair k is unique minimizer only for i > A[k] (no other same-b pair covers i)
            eff_L = max(L, A[k] + 1)
            eff_R = min(R, a_k)

            if eff_L <= eff_R:
                s = (prefix_m2[eff_R] - prefix_m2[eff_L - 1]) - (eff_R - eff_L + 1) * b_k
                best_improvement = max(best_improvement, s)

        return total + best_improvement

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        INF = n + 1

        # Step 1: For each a-value, track min1, min2, cnt1
        min1 = {}
        min2 = {}
        cnt1 = {}

        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if a not in min1:
                min1[a] = b
                min2[a] = INF
                cnt1[a] = 1
            else:
                if b < min1[a]:
                    min2[a] = min1[a]
                    min1[a] = b
                    cnt1[a] = 1
                elif b == min1[a]:
                    cnt1[a] += 1
                elif b < min2[a]:
                    min2[a] = b

        # Step 2: Compute R[i] = min of min1[a] for a >= i (sweep right to left)
        R = [INF] * (n + 2)
        current_min = INF
        for i in range(n, 0, -1):
            if i in min1:
                current_min = min(current_min, min1[i])
            R[i] = current_min

        # Step 3: Identify record breakers (positions where min1[a] < R[a+1])
        rbs = []
        for a in range(n, 0, -1):
            if a in min1 and min1[a] < R[a + 1]:
                rbs.append((a, min1[a]))

        m = len(rbs)
        rb_set = set(a for a, b in rbs)

        # Step 4: Compute h[i] = running min from right over non-RB positions only
        h = [INF] * (n + 2)
        current_h = INF
        for i in range(n, 0, -1):
            if i in min1 and i not in rb_set:
                current_h = min(current_h, min1[i])
            h[i] = current_h

        # Step 5: Total valid subarrays with all pairs present
        total_valid = 0
        for i in range(1, n + 1):
            total_valid += max(0, R[i] - i)

        # Step 6: For each RB, compute delta if removed; take max
        max_delta = 0
        for j in range(m):
            a_j, b_j = rbs[j]
            # If multiple pairs share this (a, min_b), removing one doesn't change R
            if cnt1[a_j] > 1:
                continue

            a_next = rbs[j + 1][0] if j + 1 < m else 0
            seg_start = a_next + 1
            seg_end = a_j

            b_prev = rbs[j - 1][1] if j > 0 else INF
            eff_new = min2[a_j]  # second min b at position a_j (or INF)

            delta = 0
            for i in range(seg_start, seg_end + 1):
                r_new = min(b_prev, eff_new, h[i])
                delta += max(0, r_new - i) - max(0, b_j - i)

            if delta > max_delta:
                max_delta = delta

        return total_valid + max_delta

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        from collections import defaultdict

        pairs = []
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            pairs.append((a, b))

        by_a = defaultdict(list)
        for idx, (a, b) in enumerate(pairs):
            by_a[a].append((b, idx))

        INF = n + 1
        val1, cnt1 = INF, 0
        val2, cnt2 = INF, 0
        owner_idx = -1

        num_pairs = len(pairs)
        count_p = [0] * num_pairs
        sum2_p = [0] * num_pairs

        S_all = 0

        for i in range(n, 0, -1):
            for b, idx in by_a.get(i, []):
                if b < val1:
                    val2, cnt2 = val1, cnt1
                    val1, cnt1 = b, 1
                    owner_idx = idx
                elif b == val1:
                    cnt1 += 1
                    owner_idx = -1
                elif b < val2:
                    if b == val2:
                        cnt2 += 1
                    else:
                        val2, cnt2 = b, 1
                elif b == val2:
                    cnt2 += 1

            S_all += val1 - i

            if cnt1 == 1:
                count_p[owner_idx] += 1
                sum2_p[owner_idx] += val2

        max_gain = 0
        for p in range(num_pairs):
            gain = sum2_p[p] - pairs[p][1] * count_p[p]
            max_gain = max(max_gain, gain)

        return S_all + max_gain

