class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)

        # Compute prefix sums of durations
        prefixSum = [0] * (n + 1)
        for i in range(n):
            prefixSum[i + 1] = prefixSum[i] + endTime[i] - startTime[i]

        totalDuration = prefixSum[n]

        # A[a] = prefixSum[a+1] - endTime[a]
        # B[b] = startTime[b] - prefixSum[b]
        A = [prefixSum[i + 1] - endTime[i] for i in range(n)]
        B = [startTime[i] - prefixSum[i] for i in range(n)]

        tailFree = eventTime - totalDuration

        def can_achieve(X):
            # 1. First segment: fix meeting b, move all before it (cost = b <= k)
            max_b = min(k, n - 1)
            for b in range(max_b + 1):
                if B[b] >= X:
                    return True

            # 2. Middle segment: fix meetings a and b (consecutive fixed), move between them
            #    cost = b - a - 1 <= k, so a >= b - k - 1
            #    Use sliding window maximum of A
            dq = deque()
            for b in range(n):
                # Add index b-1 to window
                if b - 1 >= 0:
                    while dq and A[dq[-1]] <= A[b - 1]:
                        dq.pop()
                    dq.append(b - 1)

                # Remove out-of-window elements (a must be >= b - k - 1)
                left = max(0, b - k - 1)
                while dq and dq[0] < left:
                    dq.popleft()

                if dq and A[dq[0]] + B[b] >= X:
                    return True

            # 3. Last segment: fix meeting a, move all after it (cost = n-1-a <= k)
            min_a = max(0, n - 1 - k)
            for a in range(min_a, n):
                if A[a] + tailFree >= X:
                    return True

            return False

        # Binary search on the answer
        lo, hi = 0, eventTime
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can_achieve(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

