class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        for start in range(2 * n - 1):
            # Determine starting position of this diagonal
            if start < n:
                r, c = 0, start
            else:
                r, c = start - n + 1, 0

            # Collect elements along this diagonal
            diag = []
            i, j = r, c
            while i < n and j < n:
                diag.append((i, j, grid[i][j]))
                i += 1
                j += 1

            # Sort based on which triangle the diagonal belongs to
            if r >= c:  # bottom-left triangle (including main diagonal)
                diag.sort(key=lambda x: -x[2])  # non-increasing
            else:  # top-right triangle
                diag.sort(key=lambda x: x[2])  # non-decreasing

            # Place sorted values back
            for i, j, val in diag:
                grid[i][j] = val

        return grid

